-- BioMatch PostgreSQL schema. OAuth is intentionally postponed.
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, display_name VARCHAR(18) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS learning_progress (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, xp INTEGER NOT NULL DEFAULT 0 CHECK(xp>=0), answers INTEGER NOT NULL DEFAULT 0, correct INTEGER NOT NULL DEFAULT 0, streak INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS question_attempts (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id VARCHAR(80) NOT NULL, selected_option SMALLINT NOT NULL CHECK(selected_option BETWEEN 0 AND 3), is_correct BOOLEAN NOT NULL, xp_earned INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS friendships (id BIGSERIAL PRIMARY KEY, requester_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, addressee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(16) NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(requester_id,addressee_id), CHECK(requester_id<>addressee_id));
CREATE TABLE IF NOT EXISTS direct_messages (id BIGSERIAL PRIMARY KEY, sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, body VARCHAR(240) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS challenges (id BIGSERIAL PRIMARY KEY, challenger_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, challenged_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(16) NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
